import { createReadStream } from 'node:fs';
import { mkdir, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { randomBytes } from 'node:crypto';

// Keys are generated by newStorageKey only. This pattern is the second line of defence against
// path traversal if a key ever came from somewhere unexpected.
const KEY_PATTERN = /^[a-f0-9]{2}\/[a-f0-9]{32}(?:-t)?$/;

/** A random storage key such as "ab/ab12...". Never derived from user input. */
export function newStorageKey() {
  const hex = randomBytes(16).toString('hex');
  return { key: `${hex.slice(0, 2)}/${hex}`, thumbnailKey: `${hex.slice(0, 2)}/${hex}-t` };
}

/**
 * Storage driver interface: put(key, buffer), get(key) -> { stream, size } | null,
 * delete(key), signedUrl(key). A cloud driver (S3, R2) implements the same four methods and may
 * return a real signed URL; the local driver returns null so the server streams the bytes itself.
 */
export function createLocalStorage({ baseDir }) {
  const root = path.resolve(baseDir);

  function resolveKey(key) {
    if (!KEY_PATTERN.test(key)) {
      throw new Error('Invalid storage key');
    }
    const target = path.resolve(root, key);
    if (!target.startsWith(root + path.sep)) {
      throw new Error('Invalid storage key');
    }
    return target;
  }

  return {
    async put(key, buffer) {
      const target = resolveKey(key);
      await mkdir(path.dirname(target), { recursive: true });
      await writeFile(target, buffer, { flag: 'wx', mode: 0o640 });
    },

    async get(key) {
      const target = resolveKey(key);
      try {
        const info = await stat(target);
        return { stream: createReadStream(target), size: info.size };
      } catch (err) {
        if (err.code === 'ENOENT') {
          return null;
        }
        throw err;
      }
    },

    async delete(key) {
      await rm(resolveKey(key), { force: true });
    },

    async signedUrl() {
      return null;
    },
  };
}
